  const fw = max > 0 ? Math.max(0, Math.floor(cur / max * w)) : 0;
  if (fw > 0) rrect(x, y, fw, h, 5, fg);
  rrect(x, y, w, h, 5, null, '#fff', 2);
  font(16, true);
  const v = `${cur}/${max}`, lw = textW(label), vw = textW(v);
